import{_ as e,o as a,c as s,ag as i}from"./chunks/framework.CxkNbRKf.js";const o="/nada-documentation/images/image223.png",n="/nada-documentation/images/image224.png",d="/nada-documentation/images/image225.png",r="/nada-documentation/images/image226.png",p="/nada-documentation/images/image227.png",c="/nada-documentation/images/image228.png",l="/nada-documentation/images/image229.png",h="/nada-documentation/images/image230.png",m="/nada-documentation/images/image231.png",u="/nada-documentation/images/image232.png",g="/nada-documentation/images/image233.png",f="/nada-documentation/images/image234.png",b="/nada-documentation/images/image235.png",D=JSON.parse('{"title":"Data deposit administration","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/data-deposit-admin.md","filePath":"admin-guide/web-ui/data-deposit-admin.md","lastUpdated":1786379412000}'),k={name:"admin-guide/web-ui/data-deposit-admin.md"};function _(y,t,w,q,v,T){return a(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="data-deposit-administration" tabindex="-1">Data deposit administration <a class="header-anchor" href="#data-deposit-administration" aria-label="Permalink to &quot;Data deposit administration&quot;">​</a></h1><h2 id="access-deposits" tabindex="-1">Access deposits <a class="header-anchor" href="#access-deposits" aria-label="Permalink to &quot;Access deposits&quot;">​</a></h2><p>Administrators can access deposits from the Data Deposit menu. Deposits can be filtered by workflow status or found using the keyword search function. The administrator can view a list of deposits at each stage of the workflow, see what is in the pipeline (draft and submitted projects); review deposits that are still in draft status and feedback to depositors before they submit.</p><p><img src="'+o+'" alt=""></p><p>For each deposit, there are three primary actions that can be performed by an administrator: Assign, Edit and Delete.</p><h2 id="assign-tasks" tabindex="-1">Assign tasks <a class="header-anchor" href="#assign-tasks" aria-label="Permalink to &quot;Assign tasks&quot;">​</a></h2><p><img src="'+n+'" alt=""></p><p>An administrator can assign a deposit to a curator, who also has administrative rights to access the deposit admin site. The system sends a notification to the assigned curator, and tags to inform informs other curators on who is managing the deposit. To assign a deposit to a curator, click the assign link then select the assignee from the list of admins and click submit.</p><p><img src="'+d+'" alt=""></p><p>Once a deposit is assigned, a tag is displayed next to the deposit with the initials of the assigned curator. The tag is color coded to signal the status (work in progress/resolved). The default status for assigned projects is work in progress. This can be updated by the curator once it is resolved. This status is independent of the deposit workflow status and is updated separately.</p><p><img src="'+r+'" alt=""></p><h2 id="features-to-keep-track-of-assigned-tasks" tabindex="-1">Features to keep track of assigned tasks <a class="header-anchor" href="#features-to-keep-track-of-assigned-tasks" aria-label="Permalink to &quot;Features to keep track of assigned tasks&quot;">​</a></h2><p>An administrator can view all active tasks by using this url:</p><p>Catalog url+ <strong>/admin/datadeposit/tasks</strong></p><p><img src="'+p+'" alt=""></p><p>A curator/admin can view their tasks by using this url: Catalog url+ <strong>/admin/datadeposit/tasks/my_tasks</strong></p><p>Tasks are listed in order starting with deposit projects assigned to the curator/admin, followed by deposits assigned by the admin to others.</p><p><img src="'+c+'" alt=""></p><h2 id="edit-deposits-manage-projects" tabindex="-1">Edit deposits (Manage projects) <a class="header-anchor" href="#edit-deposits-manage-projects" aria-label="Permalink to &quot;Edit deposits (Manage projects)&quot;">​</a></h2><p><img src="'+l+'" alt=""></p><p>The Edit link opens a Manage Projects page where an administrator can manage a deposit project from the following tabs:</p><h2 id="project-information" tabindex="-1">Project information <a class="header-anchor" href="#project-information" aria-label="Permalink to &quot;Project information&quot;">​</a></h2><p>The administrator can review all submitted project information on one page including study description, embargo notes (if provided), a list of uploaded files and citations. From this tab, an administrator can also:</p><ul><li><p>view a summary of the deposit. Contents of this page can be printed</p><blockquote><p>or saved by right clicking and selecting the desired action.</p></blockquote></li><li><p>download the metadata in DDI xml and RDF format. These files are</p><blockquote><p>machine readable and can be ingested by metadata editors like Nesstar Publisher or uploaded to NADA</p></blockquote></li></ul><p><strong>NOTE:</strong> Citations provided by the depositor are displayed in the project information but not included in the DDI, these will need to be added to the citation repository and attached to the study separately.</p><p><img src="'+h+'" alt=""></p><h2 id="process-update-status" tabindex="-1">Process (Update Status) <a class="header-anchor" href="#process-update-status" aria-label="Permalink to &quot;Process (Update Status)&quot;">​</a></h2><blockquote><p>From this tab, an administrator can select and update the status of the deposit to any of the available statuses (draft, accepted, processed, closed) and notify the depositor as well as collaborators by email. Reopen sets the status of a project to draft. <img src="'+m+'" alt=""></p></blockquote><p><strong>NOTE:</strong> Since the data deposit system does not automatically publish or add content to the catalog and archive, when the administrator reviews and accepts a deposit, they will transfer the deposited resources to the archive and file them under a unique study ID. This ID will also be used to identify the study in the NADA catalog if the data gets listed in the catalog. The deposit, archiving and publishing processes are not directly linked, so recording the study ID in data deposit when updating the deposit status helps to identify the deposit project with the study in the archive and catalog.</p><h2 id="files-access-uploaded-files" tabindex="-1">Files (Access uploaded files) <a class="header-anchor" href="#files-access-uploaded-files" aria-label="Permalink to &quot;Files (Access uploaded files)&quot;">​</a></h2><blockquote><p>This tab lists all the files uploaded to the project, indicates where they are stored, and provides their download links.</p><p><img src="'+u+'" alt=""></p></blockquote><h2 id="communicate" tabindex="-1">Communicate <a class="header-anchor" href="#communicate" aria-label="Permalink to &quot;Communicate&quot;">​</a></h2><p>The Communicate tab allows the administrator to email depositors and collaborators regarding deposits without leaving the deposit site. Emails sent this way are logged in the project deposit history and are useful for reference e.g if updates on embargo dates are sent via email.</p><blockquote><p><img src="'+g+'" alt=""></p></blockquote><h2 id="deposit-history" tabindex="-1">Deposit History <a class="header-anchor" href="#deposit-history" aria-label="Permalink to &quot;Deposit History&quot;">​</a></h2><p>The deposit history tab provides a log of changes made to the deposit. If a depositor updates a deposit, the administrator is informed of the changes in the deposit.</p><blockquote><p><img src="'+f+'" alt=""></p></blockquote><h2 id="delete-projects" tabindex="-1">Delete projects <a class="header-anchor" href="#delete-projects" aria-label="Permalink to &quot;Delete projects&quot;">​</a></h2><p><img src="'+b+'" alt=""></p><p>The delete link enables the administrator to delete deposits projects. To avoid inadvertent deletion, the system will request the confirmation before deleting a project.</p>',40)])])}const P=e(k,[["render",_]]);export{D as __pageData,P as default};
